// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 feeBps, uint256 premium, address taker, address recipient) public {
        vm.assume(taker != address(0) && recipient != address(0) && taker != address(c));
        vm.assume(recipient != address(c));
        feeBps = bound(feeBps, 1, 29);
        premium = bound(premium, 1000, type(uint128).max);

        // deploy adversarial counterparties:
        // FakeToken is the base asset (a contract with code, transfers always succeed)
        // Maker1271 is the order maker, approving via ERC-1271 so no raw signature is needed
        FakeToken token = new FakeToken();
        Maker1271 maker = new Maker1271();

        c.setFee(feeBps);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = new bytes(0);

        vm.prank(taker);
        c.fillOrder(order, sig, floorAssetTokenIds);

        uint256 expectedFee = (premium * feeBps) / 1000;
        assertGt(c.unclaimedFees(address(token)), 0);
        assertEq(c.unclaimedFees(address(token)), expectedFee);

        // owner withdraws fees (test contract is the owner)
        c.withdrawFees(address(token), recipient);

        // RULE: after withdrawFees, the recorded fee balance for the asset MUST be zero.
        assertTrue(c.unclaimedFees(address(token)) == 0);
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }
}

contract Maker1271 {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e; // IERC1271.isValidSignature.selector
    }
}
